// Short answer-feedback sounds, synthesized on the fly via the Web Audio API (no audio files needed).

let audioCtx = null;

function getAudioContext() {
  if (!audioCtx) {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return null;
    audioCtx = new AudioContextClass();
  }
  if (audioCtx.state === 'suspended') {
    audioCtx.resume();
  }
  return audioCtx;
}

function playTone(ctx, { frequency, startTime, duration, type = 'sine', peakGain = 0.2, destination }) {
  const oscillator = ctx.createOscillator();
  const gainNode = ctx.createGain();

  oscillator.type = type;
  oscillator.frequency.setValueAtTime(frequency, startTime);

  gainNode.gain.setValueAtTime(0, startTime);
  gainNode.gain.linearRampToValueAtTime(peakGain, startTime + 0.01);
  gainNode.gain.exponentialRampToValueAtTime(0.0001, startTime + duration);

  oscillator.connect(gainNode);
  gainNode.connect(destination || ctx.destination);

  oscillator.start(startTime);
  oscillator.stop(startTime + duration);
}

function playCorrectSound() {
  if (!getTriviaSettings().soundEffects) return;
  const ctx = getAudioContext();
  if (!ctx) return;
  const now = ctx.currentTime;
  // Short two-note ascending chime (A5 -> E6).
  playTone(ctx, { frequency: 880.0, startTime: now, duration: 0.12, type: 'sine', peakGain: 0.22 });
  playTone(ctx, { frequency: 1318.5, startTime: now + 0.09, duration: 0.18, type: 'sine', peakGain: 0.22 });
}

function playWrongSound() {
  if (!getTriviaSettings().soundEffects) return;
  const ctx = getAudioContext();
  if (!ctx) return;
  const now = ctx.currentTime;
  // Two dissonant descending tones ("uh-oh" style incorrect-answer sound).
  playTone(ctx, { frequency: 622.3, startTime: now, duration: 0.16, type: 'triangle', peakGain: 0.4 });
  playTone(ctx, { frequency: 493.9, startTime: now + 0.14, duration: 0.28, type: 'triangle', peakGain: 0.4 });
}

// Background clock-tick while a question timer is running.
// Scheduling uses the AudioContext's own clock (not chained setTimeout delays), so ticks stay
// locked to real seconds instead of drifting from JS event-loop jitter. A lightweight 50ms poll
// just looks ahead and books any tick that falls due, so there is no per-tick timer overhead.
const TICK_LOOKAHEAD_SEC = 0.15;
const TICK_POLL_MS = 50;

let tickPollId = null;
let tickGeneration = 0;
let tickIsTock = false;
let clickNoiseBuffer = null;

// A short burst of white noise run through a resonant bandpass filter reads as a
// mechanical "click" rather than an electronic beep - the same trick real clock-app
// sound effects use to fake an escapement tick without a recorded sample.
function getClickNoiseBuffer(ctx) {
  if (clickNoiseBuffer && clickNoiseBuffer.sampleRate === ctx.sampleRate) return clickNoiseBuffer;
  const durationSec = 0.06;
  const buffer = ctx.createBuffer(1, Math.ceil(ctx.sampleRate * durationSec), ctx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < data.length; i += 1) {
    data[i] = Math.random() * 2 - 1;
  }
  clickNoiseBuffer = buffer;
  return buffer;
}

function playClickAt(ctx, time, { filterFrequency, peakGain, duration, destination }) {
  const source = ctx.createBufferSource();
  source.buffer = getClickNoiseBuffer(ctx);

  const bandpass = ctx.createBiquadFilter();
  bandpass.type = 'bandpass';
  bandpass.frequency.setValueAtTime(filterFrequency, time);
  bandpass.Q.value = 1.4;

  const gainNode = ctx.createGain();
  gainNode.gain.setValueAtTime(0, time);
  gainNode.gain.linearRampToValueAtTime(peakGain, time + 0.002);
  gainNode.gain.exponentialRampToValueAtTime(0.0001, time + duration);

  source.connect(bandpass);
  bandpass.connect(gainNode);
  gainNode.connect(destination || ctx.destination);

  source.start(time);
  source.stop(time + duration);
}

function scheduleTickAt(ctx, time, urgent) {
  // Real clocks alternate a slightly higher "tick" and lower "tock" - alternating the
  // filter frequency between the two calls recreates that without extra scheduling.
  const isTick = tickIsTock;
  tickIsTock = !tickIsTock;

  const filterFrequency = isTick
    ? (urgent ? 3400 : 3000)
    : (urgent ? 2500 : 2100);
  const peakGain = urgent ? 0.5 : 0.32;
  const duration = urgent ? 0.035 : 0.045;

  playClickAt(ctx, time, { filterFrequency, peakGain, duration });
}

function startTickingClock(getSecondsLeft, urgentThreshold) {
  stopTickingClock();
  if (!getTriviaSettings().soundEffects) return;
  const ctx = getAudioContext();
  if (!ctx) return;

  tickIsTock = false;
  const myGeneration = ++tickGeneration;
  let nextTickTime = ctx.currentTime;

  const pollLoop = () => {
    if (myGeneration !== tickGeneration) return;

    const secondsLeft = getSecondsLeft();
    if (!(secondsLeft > 0)) {
      stopTickingClock();
      return;
    }

    const urgent = secondsLeft <= urgentThreshold;
    const interval = urgent ? 0.5 : 1.0;

    while (nextTickTime < ctx.currentTime + TICK_LOOKAHEAD_SEC) {
      scheduleTickAt(ctx, nextTickTime, urgent);
      nextTickTime += interval;
    }

    tickPollId = setTimeout(pollLoop, TICK_POLL_MS);
  };

  pollLoop();
}

function stopTickingClock() {
  tickGeneration += 1;
  if (tickPollId) {
    clearTimeout(tickPollId);
    tickPollId = null;
  }
}

// Driving background music for a game session: a looping mp3 that plays for exactly as
// long as the round's global timer runs. startBackgroundMusic()/stopBackgroundMusic() mark
// session intent - called alongside startGlobalTimer()/stopGlobalTimer() by the page
// controllers - so the track starts the moment answering begins and stops the moment the
// round's clock ends. Playback also reacts live to the backgroundMusic setting being
// toggled mid-session (see the triviaSettingsChanged listener below), so the settings modal
// can mute it instantly.
const MUSIC_TRACK_URL = 'sounds/prettyjohn1-soft-499242.mp3';
const MUSIC_FADE_OUT_SEC = 0.6;
const MUSIC_GAIN = 0.35;

let musicSessionRequested = false;
let musicAudioEl = null;
let musicFadeRaf = null;

// Call once when a game session (solo round or duel) actually begins.
function startBackgroundMusic() {
  musicSessionRequested = true;
  restartMusicPlayback();
}

// Call once when the session ends (result screen). Also invoked internally whenever the
// backgroundMusic setting flips off mid-session.
function stopBackgroundMusic() {
  musicSessionRequested = false;
  stopMusicPlayback();
}

// Played as a plain HTMLMediaElement (its own .volume, no AudioContext/MediaElementSource)
// deliberately: routing it through the shared AudioContext used by the oscillator-based tick
// sound tied the tick's autoplay gating to the music element's stricter one, so on iOS the
// suspended context silenced ticks too until the music itself got unlocked. Keeping them on
// separate playback paths lets ticks work as soon as the context is resumed, independent of
// the music element's own unlock state.
function restartMusicPlayback() {
  stopMusicPlayback();
  if (!musicSessionRequested || !getTriviaSettings().backgroundMusic) return;

  musicAudioEl = new Audio(MUSIC_TRACK_URL);
  musicAudioEl.loop = true;
  musicAudioEl.volume = MUSIC_GAIN;
  musicAudioEl.play().catch(() => {});
}

function stopMusicPlayback() {
  if (musicFadeRaf) {
    cancelAnimationFrame(musicFadeRaf);
    musicFadeRaf = null;
  }
  if (musicAudioEl) {
    const audioEl = musicAudioEl;
    const startVolume = audioEl.volume;
    const startTime = performance.now();
    const fadeStep = () => {
      const t = Math.min((performance.now() - startTime) / (MUSIC_FADE_OUT_SEC * 1000), 1);
      audioEl.volume = startVolume * (1 - t);
      if (t < 1) {
        musicFadeRaf = requestAnimationFrame(fadeStep);
      } else {
        musicFadeRaf = null;
        audioEl.pause();
        audioEl.currentTime = 0;
      }
    };
    musicFadeRaf = requestAnimationFrame(fadeStep);
  }
  musicAudioEl = null;
}

window.addEventListener('triviaSettingsChanged', () => {
  if (musicSessionRequested) restartMusicPlayback();
});

// iOS Safari only lets an AudioContext resume from inside a real user-gesture event handler.
// startBackgroundMusic()/startTickingClock() fire from the round's DOMContentLoaded handler,
// which isn't a gesture, so the context stays suspended and both stay silent - until something
// like a real tap (e.g. the settings toggle's click handler) happens to resume it later. Prime
// the context on the page's first genuine tap/click/key instead of waiting for that.
(function unlockAudioOnFirstGesture() {
  const unlock = () => {
    document.removeEventListener('touchend', unlock, true);
    document.removeEventListener('mousedown', unlock, true);
    document.removeEventListener('keydown', unlock, true);
    const ctx = getAudioContext();
    if (ctx && ctx.state === 'suspended') ctx.resume();
    if (musicSessionRequested && (!musicAudioEl || musicAudioEl.paused)) {
      restartMusicPlayback();
    }
  };
  document.addEventListener('touchend', unlock, true);
  document.addEventListener('mousedown', unlock, true);
  document.addEventListener('keydown', unlock, true);
})();

// Win celebration: applause + crowd cheer. Rendered offline as a real 16-bit PCM WAV
// (broadband highpass/lowpass shaping, not narrow resonant bandpass, so it reads as a
// percussive clap/crowd swell instead of an electronic tone) and embedded below as a
// base64 data URI - no separate asset file to ship, no network fetch at runtime.
const APPLAUSE_SOUND_DATA_URI = 'data:audio/wav;base64,';

function playApplauseSound() {
  if (!getTriviaSettings().soundEffects) return;
  const audio = new Audio(APPLAUSE_SOUND_DATA_URI);
  audio.play().catch(() => {});
}
